import math
import numpy as np
from scipy.optimize import least_squares

_params = None

def _value(row, p):
    a, b, c, k, threshold = p
    u = float(row['u_now'])
    s = float(row['s_grad'])
    return (a - b * s / (1.0 + s)) * u / (1.2 + u) + c * math.sqrt(max(0.0, u)) - k * max(0.0, s - threshold) * u

def fit(train_rows):
    global _params
    def residual(p):
        return np.array([_value(r, p) - float(r['y']) for r in train_rows])
    best = None
    for threshold in (2.50, 2.59, 2.68):
        result = least_squares(residual, [6.0, 1.0, 1.0, 1.5, threshold], bounds=([-np.inf, -np.inf, -np.inf, 0.0, 2.44], [np.inf, np.inf, np.inf, np.inf, 2.78]), max_nfev=10000, xtol=1e-12, ftol=1e-12, gtol=1e-12)
        if best is None or np.dot(result.fun, result.fun) < np.dot(best.fun, best.fun):
            best = result
    _params = best.x
    return _params

def predict(row):
    return float(_value(row, _params))
